            if A[i] != B[i]:
                if A[i] not in adj:
                    adj[A[i]] = set()
                adj[A[i]].add(B[i])

        # Build our graph and count needed operations
        # Key insight: this is counting edges with path constraint
        vis = set()
        ans = 0
        for start in sorted(adj.keys()):
            if start not in vis:
                # Start a traversal
                stack = [start]
                components = set()
                while stack:
                    node = stack.pop()
                    if node not in vis:
                        vis.add(node)
                        components.add(node)
                        if node in adj:
                            for target in adj[node]:
                                if target not in vis:
                                    vis.add(target)
                                    stack.append(target)
                        for target in adj:
                            if start in adj:
                                for target2 in adj[start]:
                                    if target in adj and target2 in adj[target]:
                                        pass
                ans += 1

        # Count unique transformation pairs
        pairs = set()
        for i in range(n):
            if A[i] != B[i]:
                pairs.add((A[i], B[i]))

        # Build graph and count components
        graph = {}
        for src, dst in pairs:
            if src not in graph:
                graph[src] = []
            graph[src].append(dst)

        visited = set()
        count = 0
        all_nodes = set()
        for src, dsts in graph.items():
            all_nodes.add(src)
            for dst in dsts:
                all_nodes.add(dst)

        for node in all_nodes:
            if node not in visited:
                visited.add(node)
                count += 1

        # Final answer based on graph structure
        edges = len(pairs)
        ans = edges
        if not pairs:
            ans = 0
        else:
            # Count connected components in character graph
            comp = {}
            for src in all_nodes:
                if src not in comp:
                    queue = [src]
                    visit = set()
                    while queue:
                        c = queue.pop()
                        if c in visit:
                            continue
                        visit.add(c)
                        comp[c] = True
                        for neighbor in graph.get(c, []):
                            if neighbor not in visit:
                                queue.append(neighbor)

        return ans in results

