        """Check if a sequence is a geometric progression."""
        if len(seq) <= 2:
            return True

        all_zero = all(x == 0 for x in seq)
        if all_zero:
            return True

        first = -1
        for i in range(len(seq)):
            if seq[i] != 0:
                first = i
                break

        if first == -1:
            return True

        if seq[first] == 0:
            return True

        second = -1
        for i in range(first + 1, len(seq)):
            if seq[i] != 0:
                second = i
                break

        if second == -1:
            return True

        if seq[second] == 0:
            for k in range(second + 1, len(seq)):
                if seq[k] != 0:
                    return False
            return True

        ratio_num = seq[second]
        ratio_den = seq[first]

        for k in range(second + 1, len(seq)):
            prev = seq[k-1]
            curr = seq[k]
            if prev == 0:
                continue
            if ratio_num * prev != ratio_den * curr:
                return False

        return True

    if is_gp(arr):
        return '0\n'

    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

    return '2\n'
