class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = collections.deque([s])
        while q:
            u = q.popleft()
            for v, cap, _ in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] != self.level[u] + 1 or cap == 0:
                continue
            pushed = self.dfs(v, t, min(flow, cap), ptr)
            if pushed == 0:
                continue
            self.graph[u][i][1] -= pushed
            self.graph[v][rev][1] += pushed
            return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

def get_prime_factor_exponents(n, p):
    """Count exponent of prime p in n"""
    count = 0
    while n > 0 and n % p == 0:
        count += 1
        n //= p
    return count

def get_prime_factors(n):
    """Get all prime factors of n"""
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    pairs = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        pairs.append((u - 1, v - 1))  # Convert to 0-indexed

    all_primes = set()
    for x in a:
        all_primes.update(get_prime_factors(x))

    result = 0
    source, sink = 2 * n, 2 * n + 1

    for p in all_primes:
        exponents = [get_prime_factor_exponents(x, p) for x in a]

        dinic = Dinic(sink + 1)

        # Odd 1-indexed positions (even 0-indexed) connect to source
        for i in range(n):
            if (i + 1) % 2 == 1:
                dinic.add_edge(source, i, exponents[i])

        # Odd 1-indexed positions connect to sink
        for i in range(n):
            if (i + 1) % 2 == 0:
                dinic.add_edge(i, sink, exponents[i])

        # Good pairs
        for u, v in pairs:
            if (u + 1) % 2 == 1:
                dinic.add_edge(u, v, float('inf'))
            else:
                dinic.add_edge(v, u, float('inf'))

        result += dinic.max_flow(source, sink)

    return f"{result}"

