            if start_with_add:
                # Start with add: positions 0,2,4... use +, positions 1,3,5... use -
                if i % 2 == 0:
                    new_row.append((current[i] + current[i + 1]) % MOD)
                else:
                    new_row.append((current[i] - current[i + 1]) % MOD)
            else:
