                    new_row.append((current[i] - current[i + 1]) % MOD)
                else:
                    new_row.append((current[i] + current[i + 1]) % MOD)

        current = new_row

        # For next row: if this row started with add, next starts with sub, vice versa
        start_with_add = not start_with_add

    result = current[0] % MOD
    return f"\n{result}\n"
