        if a_pts < thresh and b_pts >= thresh:
            return False
        if b_pts < thresh and a_pts >= thresh:
            return False
        if a_pts >= thresh and b_pts >= thresh:
            return False
        if a_pts < thresh - 2:
            return False
        if b_pts < thresh - 2:
            return False

        if a_pts > b_pts:
            return (a_pts >= thresh and a_pts - b_pts >= 2 or
                   a_pts == thresh and b_pts == thresh - 1)
        else:
            return (b_pts >= thresh and b_pts - a_pts >= 2 or
                   b_pts == thresh and a_pts == thresh - 1)

